-- CANDIDATE ONLY; no production installation or role memberships.
-- Reads canonical receipt DATA. No receipt producer or operating approval is
-- installed. ProtectedIndustryProductionGuard remains required at commit.
-- Depends on postwar-industry-production-source.sql; uses its exact original,
-- admission/permit/head locks and existing private owner/reader roles.
begin;
grant usage,create on schema world_v2 to world_v2_industry_source_owner;
grant select on world_v2.authoritative_event to world_v2_industry_source_owner;
-- Baseline event history is not globally RLS-enabled here. Fixed SECURITY
-- DEFINER predicates, NOLOGIN owner and no reader raw SELECT are the boundary.
create policy industry_operating_owner_event on world_v2.authoritative_event for select to world_v2_industry_source_owner using(current_user='world_v2_industry_source_owner'and world_id=current_setting('econmind.industry_source_world',true));
create policy industry_operating_owner_event_fence on world_v2.authoritative_event as restrictive for select to world_v2_industry_source_owner using(current_user='world_v2_industry_source_owner'and world_id=current_setting('econmind.industry_source_world',true));
create function world_v2.lock_postwar_industry_operating_receipts(p_world text,p_country text,p_facility text,p_version bigint,p_sequence bigint,p_requirements jsonb)
returns table(original jsonb,frames jsonb)language plpgsql security definer set search_path=pg_catalog as $$
declare effective name;base record;req jsonb;ev world_v2.authoritative_event%rowtype;c world_v2.command_submission%rowtype;r world_v2.command_receipt%rowtype;event_rows jsonb;result jsonb:='[]'::jsonb;target_count integer;
begin
 effective:=case when current_setting('role')='none'then session_user else current_setting('role')::name end;
 if not pg_has_role(effective,'world_v2_industry_source_reader','MEMBER')or pg_has_role(effective,'world_v2_industry_source_owner','MEMBER')or pg_has_role(effective,'world_v2_industry_source_publisher','MEMBER')or has_schema_privilege(effective,'world_v2','CREATE')or exists(select 1 from pg_roles where rolname=effective and(rolsuper or rolbypassrls or rolcreatedb or rolcreaterole or rolreplication))then raise exception 'INDUSTRY_OPERATING_FIXED_READER_REQUIRED'using errcode='42501';end if;
 if current_setting('transaction_read_only')<>'off'or current_setting('transaction_isolation')not in('repeatable read','serializable')then raise exception 'INDUSTRY_OPERATING_STABLE_LOCKING_TRANSACTION_REQUIRED'using errcode='25000';end if;
 if jsonb_typeof(p_requirements)is distinct from 'array'or jsonb_array_length(p_requirements)not between 1 and 9 or octet_length(p_requirements::text)>8192 then raise exception 'INDUSTRY_OPERATING_BOUNDED_REQUIREMENTS_REQUIRED'using errcode='22023';end if;
 for req in select value from jsonb_array_elements(p_requirements)loop
  if jsonb_typeof(req)is distinct from 'object'or(select count(*)from jsonb_object_keys(req))<>2 or not(req?'kind'and req?'receiptId')or req->>'kind'not in('WORK','MAINTENANCE','PAID_COST','POWER_DELIVERY','WATER_DELIVERY','LOGISTICS_DELIVERY','OPERATING_PERMISSION','TECHNOLOGY_RIGHT','RECIPE')or jsonb_typeof(req->'receiptId')is distinct from 'string'or length(req->>'receiptId')not between 1 and 512 then raise exception 'INDUSTRY_OPERATING_EXACT_REQUIREMENT_REQUIRED'using errcode='22023';end if;
 end loop;
 if(select count(distinct value->>'kind')from jsonb_array_elements(p_requirements))<>jsonb_array_length(p_requirements)then raise exception 'INDUSTRY_OPERATING_DUPLICATE_KIND'using errcode='22023';end if;
 select * into strict base from world_v2.lock_postwar_industry_original(p_world,p_country,p_facility,p_version,p_sequence);
 if encode(sha256(convert_to(base.document_text,'UTF8')),'hex')<>base.document_sha256 then raise exception 'INDUSTRY_OPERATING_ORIGINAL_HASH_MISMATCH'using errcode='23514';end if;
 -- The held World head excludes concurrent canonical receipt/withdrawal writers.
 -- Out-of-band restrictions remain the mandatory protected original-use driver.
 if(select count(*)from world_v2.authoritative_event e where e.world_id=p_world and e.world_version<=p_version and e.event_type in('POSTWAR_INDUSTRY_OPERATING_FACT_RECORDED_V1','POSTWAR_INDUSTRY_OPERATING_FACT_WITHDRAWN_V1'))>256 then raise exception 'INDUSTRY_OPERATING_RECEIPT_PREFIX_CAPACITY'using errcode='54000';end if;
 for req in select value from jsonb_array_elements(p_requirements)loop
  select count(*)into target_count from world_v2.authoritative_event e where e.world_id=p_world and e.world_version<=p_version and e.event_sequence<=p_sequence and e.event_type='POSTWAR_INDUSTRY_OPERATING_FACT_RECORDED_V1'and e.canonical_payload::jsonb->'operatingReceipt'->>'countryId'=p_country and e.canonical_payload::jsonb->'operatingReceipt'->>'facilityId'=p_facility and e.canonical_payload::jsonb->'operatingReceipt'->>'kind'=req->>'kind'and e.canonical_payload::jsonb->'operatingReceipt'->>'receiptId'=req->>'receiptId';
  if target_count=0 then continue;end if;
  if target_count<>1 then raise exception 'INDUSTRY_OPERATING_RECEIPT_REVISION_AMBIGUOUS'using errcode='23514';end if;
  select * into strict ev from world_v2.authoritative_event e where e.world_id=p_world and e.world_version<=p_version and e.event_sequence<=p_sequence and e.event_type='POSTWAR_INDUSTRY_OPERATING_FACT_RECORDED_V1'and e.canonical_payload::jsonb->'operatingReceipt'->>'countryId'=p_country and e.canonical_payload::jsonb->'operatingReceipt'->>'facilityId'=p_facility and e.canonical_payload::jsonb->'operatingReceipt'->>'kind'=req->>'kind'and e.canonical_payload::jsonb->'operatingReceipt'->>'receiptId'=req->>'receiptId';
  if exists(select 1 from world_v2.authoritative_event e where e.world_id=p_world and e.world_version<=p_version and e.event_sequence<=p_sequence and(e.corrects_event_id=ev.event_id or(e.event_type='POSTWAR_INDUSTRY_OPERATING_FACT_WITHDRAWN_V1'and e.canonical_payload::jsonb->>'receiptEventId'=ev.event_id)))then raise exception 'INDUSTRY_OPERATING_RECEIPT_WITHDRAWN_OR_CORRECTED'using errcode='55000';end if;
  select * into strict c from world_v2.command_submission s where s.world_id=p_world and s.command_id=ev.causation_command_id and s.country_id=p_country;
  select * into strict r from world_v2.command_receipt q where q.world_id=p_world and q.command_id=c.command_id and q.command_fingerprint=c.command_fingerprint and q.outcome='COMMITTED'and q.world_version_after=ev.world_version and q.sim_time=ev.sim_time;
  if jsonb_array_length(r.event_ids)not between 1 and 16 or octet_length(c.canonical_payload)>65536 or(select count(*)from world_v2.authoritative_event e where e.world_id=p_world and e.causation_command_id=c.command_id)<>jsonb_array_length(r.event_ids)then raise exception 'INDUSTRY_OPERATING_COMPLETE_EVENT_GROUP_REQUIRED'using errcode='23514';end if;
  if exists(select 1 from world_v2.authoritative_event e where e.world_id=p_world and e.causation_command_id=c.command_id and(octet_length(e.canonical_payload)>65536 or e.world_version<>r.world_version_after or e.event_sequence>p_sequence or e.sim_time<>c.sim_time or not(r.event_ids?e.event_id)))then raise exception 'INDUSTRY_OPERATING_EVENT_GROUP_MISMATCH'using errcode='23514';end if;
  select jsonb_agg(jsonb_build_object('causationCommandId',e.causation_command_id,'correlationId',e.correlation_id,'correctsEventId',e.corrects_event_id,'eventId',e.event_id,'eventType',e.event_type,'canonicalPayload',e.canonical_payload,'payloadHash',e.payload_sha256,'fingerprint',e.event_fingerprint,'recordedAtReal',to_char(e.recorded_at_real at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'schemaVersion',e.schema_version,'sequence',e.event_sequence::text,'simTime',e.sim_time::text,'worldId',e.world_id,'worldVersion',e.world_version::text)order by e.event_sequence)into event_rows from world_v2.authoritative_event e where e.world_id=p_world and e.causation_command_id=c.command_id;
  result:=result||jsonb_build_array(jsonb_build_object('targetEventId',ev.event_id,'command',jsonb_build_object('actorId',c.actor_id,'authSubject',c.auth_subject::text,'commandId',c.command_id,'commandType',c.command_type,'correlationId',c.correlation_id,'countryId',c.country_id,'expectedWorldVersion',c.expected_world_version::text,'fingerprint',c.command_fingerprint,'idempotencyKey',c.idempotency_key,'officeId',c.office_id,'canonicalPayload',c.canonical_payload,'payloadHash',c.payload_sha256,'schemaVersion',c.schema_version,'simTime',c.sim_time::text,'submittedAtReal',to_char(c.submitted_at_real at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'worldId',c.world_id),'events',event_rows,'receipt',jsonb_build_object('schemaVersion',r.schema_version,'worldId',r.world_id,'commandId',r.command_id,'idempotencyKey',r.idempotency_key,'commandFingerprint',r.command_fingerprint,'outcome',r.outcome,'reasonCode',r.reason_code,'transitionId',r.transition_id,'worldVersionBefore',r.world_version_before::text,'worldVersionAfter',r.world_version_after::text,'simTime',r.sim_time::text,'eventIds',r.event_ids,'recordedAtReal',to_char(r.recorded_at_real at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))));
 end loop;
 if octet_length(result::text)>1048576 then raise exception 'INDUSTRY_OPERATING_RECEIPT_TOTAL_CAPACITY'using errcode='54000';end if;
 return query select jsonb_build_object('worldVersion',p_version::text,'eventSequence',p_sequence::text,'registrationRef',base.registration_ref,'documentSha256',base.document_sha256,'seedFingerprint',base.seed_fingerprint,'admissionRef',base.admission_ref),result;
end;$$;
alter function world_v2.lock_postwar_industry_operating_receipts(text,text,text,bigint,bigint,jsonb)owner to world_v2_industry_source_owner;
revoke all on function world_v2.lock_postwar_industry_operating_receipts(text,text,text,bigint,bigint,jsonb)from public;
grant execute on function world_v2.lock_postwar_industry_operating_receipts(text,text,text,bigint,bigint,jsonb)to world_v2_industry_source_reader;
-- No raw journal is granted/returned to the reader. The fixed function builds
-- the complete actual prefix and compares every stored byte/metadata column
-- with the genuinely Core-replayed prefix supplied by the server. A view or
-- seed/head coincidence alone is insufficient. Digest is returned only AFTER
-- independent DB equality. No authority is granted by this DATA comparison.
grant select on world_v2.inventory_posting to world_v2_industry_source_owner;
create policy industry_operating_owner_inventory on world_v2.inventory_posting for select to world_v2_industry_source_owner using(current_user='world_v2_industry_source_owner'and world_id=current_setting('econmind.industry_source_world',true));
create policy industry_operating_owner_inventory_fence on world_v2.inventory_posting as restrictive for select to world_v2_industry_source_owner using(current_user='world_v2_industry_source_owner'and world_id=current_setting('econmind.industry_source_world',true));
create function world_v2.lock_postwar_industry_payment_prefix(p_world text,p_country text,p_facility text,p_version bigint,p_sequence bigint,p_expected text)
returns table(original jsonb,prefix_sha256 text)language plpgsql security definer set search_path=pg_catalog as $$
declare effective name;base record;c world_v2.command_submission%rowtype;r world_v2.command_receipt%rowtype;event_rows jsonb;financial_rows jsonb;inventory_rows jsonb;journal jsonb:='[]'::jsonb;seen bigint:=0;
begin
 effective:=case when current_setting('role')='none'then session_user else current_setting('role')::name end;
 if not pg_has_role(effective,'world_v2_industry_source_reader','MEMBER')or pg_has_role(effective,'world_v2_industry_source_owner','MEMBER')or pg_has_role(effective,'world_v2_industry_source_publisher','MEMBER')or has_schema_privilege(effective,'world_v2','CREATE')or exists(select 1 from pg_roles where rolname=effective and(rolsuper or rolbypassrls or rolcreatedb or rolcreaterole or rolreplication))then raise exception 'INDUSTRY_PAYMENT_FIXED_READER_REQUIRED'using errcode='42501';end if;
 if current_setting('transaction_read_only')<>'off'or current_setting('transaction_isolation')not in('repeatable read','serializable')then raise exception 'INDUSTRY_PAYMENT_STABLE_LOCKING_TRANSACTION_REQUIRED'using errcode='25000';end if;
 if p_version not between 1 and 256 or p_sequence not between 1 and 4096 or octet_length(p_expected)>1048576 or jsonb_typeof(p_expected::jsonb)is distinct from 'array'or jsonb_array_length(p_expected::jsonb)<>p_version then raise exception 'INDUSTRY_PAYMENT_BOUNDED_COMPLETE_PREFIX_REQUIRED'using errcode='54000';end if;
 select * into strict base from world_v2.lock_postwar_industry_original(p_world,p_country,p_facility,p_version,p_sequence);
 if encode(sha256(convert_to(base.document_text,'UTF8')),'hex')<>base.document_sha256 then raise exception 'INDUSTRY_PAYMENT_ORIGINAL_HASH_MISMATCH'using errcode='23514';end if;
 if(select count(*)from world_v2.authoritative_event e where e.world_id=p_world and e.world_version<=p_version)<>p_sequence or(select count(*)from world_v2.financial_posting_batch b where b.world_id=p_world and b.world_version_after<=p_version)>512 or(select count(*)from world_v2.inventory_posting b where b.world_id=p_world and b.world_version_after<=p_version)>512 then raise exception 'INDUSTRY_PAYMENT_PREFIX_GAP_OR_CAPACITY'using errcode='54000';end if;
 if exists(select 1 from world_v2.authoritative_event e where e.world_id=p_world and e.world_version<=p_version and not exists(select 1 from world_v2.command_receipt q where q.world_id=e.world_id and q.command_id=e.causation_command_id and q.outcome='COMMITTED'and q.world_version_after=e.world_version and q.event_ids?e.event_id))or exists(select 1 from world_v2.financial_posting_batch b where b.world_id=p_world and b.world_version_after<=p_version and not exists(select 1 from world_v2.command_receipt q where q.world_id=b.world_id and q.command_id=b.causation_command_id and q.outcome='COMMITTED'and q.world_version_before=b.world_version_before and q.world_version_after=b.world_version_after and q.event_ids=b.event_ids and q.sim_time=b.sim_time))or exists(select 1 from world_v2.inventory_posting b where b.world_id=p_world and b.world_version_after<=p_version and not exists(select 1 from world_v2.command_receipt q where q.world_id=b.world_id and q.command_id=b.causation_command_id and q.outcome='COMMITTED'and q.world_version_before=b.world_version_before and q.world_version_after=b.world_version_after and q.event_ids=b.event_ids and q.sim_time=b.sim_time))then raise exception 'INDUSTRY_PAYMENT_ORPHAN_PREFIX_FACT'using errcode='23514';end if;
 for r in select * from world_v2.command_receipt q where q.world_id=p_world and q.outcome='COMMITTED'and q.world_version_after<=p_version order by q.world_version_after loop
  seen:=seen+1;if r.world_version_before<>seen-1 or r.world_version_after<>seen then raise exception 'INDUSTRY_PAYMENT_PREFIX_VERSION_GAP'using errcode='23514';end if;
  select * into strict c from world_v2.command_submission s where s.world_id=p_world and s.command_id=r.command_id and s.command_fingerprint=r.command_fingerprint;
  select jsonb_agg(jsonb_build_object('causationCommandId',e.causation_command_id,'correlationId',e.correlation_id,'correctsEventId',e.corrects_event_id,'eventId',e.event_id,'eventType',e.event_type,'canonicalPayload',e.canonical_payload,'payloadHash',e.payload_sha256,'fingerprint',e.event_fingerprint,'recordedAtReal',to_char(e.recorded_at_real at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'schemaVersion',e.schema_version,'sequence',e.event_sequence::text,'simTime',e.sim_time::text,'worldId',e.world_id,'worldVersion',e.world_version::text)order by e.event_sequence)into event_rows from world_v2.authoritative_event e where e.world_id=p_world and e.causation_command_id=c.command_id;
  select coalesce(jsonb_agg(jsonb_build_object('intent',b.canonical_payload,'fingerprint',b.batch_fingerprint,'metadata',jsonb_build_object('worldId',b.world_id,'causationCommandId',b.causation_command_id,'worldVersionBefore',b.world_version_before::text,'worldVersionAfter',b.world_version_after::text,'simTime',b.sim_time::text,'causationEventIds',b.event_ids,'transitionBinding',b.transition_binding,'batchId',b.batch_id,'settlementCurrency',b.settlement_currency))order by b.batch_fingerprint),'[]')into financial_rows from world_v2.financial_posting_batch b where b.world_id=p_world and b.causation_command_id=c.command_id;
  select coalesce(jsonb_agg(jsonb_build_object('intent',b.canonical_payload,'fingerprint',b.posting_fingerprint,'metadata',jsonb_build_object('worldId',b.world_id,'causationCommandId',b.causation_command_id,'worldVersionBefore',b.world_version_before::text,'worldVersionAfter',b.world_version_after::text,'simTime',b.sim_time::text,'causationEventIds',b.event_ids,'transitionBinding',b.transition_binding,'postingId',b.posting_id,'operation',b.operation))order by b.posting_fingerprint),'[]')into inventory_rows from world_v2.inventory_posting b where b.world_id=p_world and b.causation_command_id=c.command_id;
  journal:=journal||jsonb_build_array(jsonb_build_object('command',jsonb_build_object('actorId',c.actor_id,'authSubject',c.auth_subject::text,'commandId',c.command_id,'commandType',c.command_type,'correlationId',c.correlation_id,'countryId',c.country_id,'expectedWorldVersion',c.expected_world_version::text,'fingerprint',c.command_fingerprint,'idempotencyKey',c.idempotency_key,'officeId',c.office_id,'canonicalPayload',c.canonical_payload,'payloadHash',c.payload_sha256,'schemaVersion',c.schema_version,'simTime',c.sim_time::text,'submittedAtReal',to_char(c.submitted_at_real at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'worldId',c.world_id),'events',event_rows,'receipt',jsonb_build_object('schemaVersion',r.schema_version,'worldId',r.world_id,'commandId',r.command_id,'idempotencyKey',r.idempotency_key,'commandFingerprint',r.command_fingerprint,'outcome',r.outcome,'reasonCode',r.reason_code,'transitionId',r.transition_id,'worldVersionBefore',r.world_version_before::text,'worldVersionAfter',r.world_version_after::text,'simTime',r.sim_time::text,'eventIds',r.event_ids,'recordedAtReal',to_char(r.recorded_at_real at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),'financialPostingBatches',financial_rows,'inventoryPostings',inventory_rows));
  if octet_length(journal::text)>1048576 then raise exception 'INDUSTRY_PAYMENT_PREFIX_BYTE_CAPACITY'using errcode='54000';end if;
 end loop;
 if seen<>p_version or journal is distinct from p_expected::jsonb then raise exception 'INDUSTRY_PAYMENT_ACTUAL_PREFIX_MISMATCH'using errcode='23514';end if;
 return query select jsonb_build_object('worldVersion',p_version::text,'eventSequence',p_sequence::text,'registrationRef',base.registration_ref,'documentText',base.document_text,'documentSha256',base.document_sha256,'seedFingerprint',base.seed_fingerprint,'admissionRef',base.admission_ref),encode(sha256(convert_to(p_expected,'UTF8')),'hex');
end;$$;
alter function world_v2.lock_postwar_industry_payment_prefix(text,text,text,bigint,bigint,text)owner to world_v2_industry_source_owner;
revoke all on function world_v2.lock_postwar_industry_payment_prefix(text,text,text,bigint,bigint,text)from public;
grant execute on function world_v2.lock_postwar_industry_payment_prefix(text,text,text,bigint,bigint,text)to world_v2_industry_source_reader;
revoke create on schema world_v2 from world_v2_industry_source_owner;
commit;
-- Recovery: stop consumers and retain canonical history and registered evidence.
-- After a committed installation, use an independently reviewed forward fix.
-- An unknown installation outcome forbids automatic retry; inspect durable
-- receipt/catalog state first. This proposal supplies no destructive recovery.
